/**
 * The installed `nomo` command, exercised as an operator meets it.
 *
 * The launcher that ends up in `~/.local/bin` is generated by a heredoc inside
 * `install-nomo.sh`, so nothing else in the repository can observe it: a broken
 * generator ships a launcher that fails on the first keystroke, at run time, on
 * a machine that is not CI. These tests run the real installer into a temporary
 * HOME, then run the launcher it wrote.
 *
 * `node` is faked on PATH so the assertions are about what the launcher does,
 * not about TUI pixels: it records the argv it was handed and drains stdin.
 * Which command those argv select is then resolved with the shipped parser
 * (`packages/cli/src/argv.ts`), so the "bare `nomo` opens the TUI" claim is
 * checked against real code rather than restated.
 */

import test from "node:test";
import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  utimesSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { parseInvocation, withDefaultTui } from "../../packages/cli/src/argv.ts";

const root = resolve(import.meta.dirname, "..", "..");
const installer = join(root, "scripts", "install-nomo.sh");
const entry = "packages/cli/bin/nomo.mjs";

/**
 * A temporary HOME with a bin directory first on PATH. The fake `node` records
 * the argv it received, NUL separated so an empty argument survives the round
 * trip, and then copies stdin, because a launcher that swallowed it would break
 * the TUI in a way nothing else here could see.
 */
function sandbox({ fakeNode = false, fakePnpm = false } = {}) {
  const home = mkdtempSync(join(tmpdir(), "nomo-install-"));
  const bin = join(home, "bin");
  mkdirSync(bin, { recursive: true });
  const argvLog = join(home, "node-argv.log");
  const stdinLog = join(home, "node-stdin.log");
  const pnpmLog = join(home, "pnpm.log");

  if (fakeNode) {
    // The installer probes `node --version` before it does anything else, so the
    // fake has to answer that one call honestly or the prereq check reads an
    // empty string and refuses a machine that is fine. Everything else is
    // recorded instead of run, which is the whole reason for the fake.
    writeFileSync(
      join(bin, "node"),
      [
        "#!/bin/sh",
        `if [ "$#" -eq 1 ] && [ "$1" = "--version" ]; then exec "${process.execPath}" "$@"; fi`,
        `printf '%s\\n' "$$" > "$NOMO_TEST_PID_LOG"`,
        `printf '%s\\0' "$@" > "$NOMO_TEST_ARGV_LOG"`,
        `cat >> "$NOMO_TEST_STDIN_LOG"`,
        "",
      ].join("\n"),
      { mode: 0o755 },
    );
  }
  if (fakePnpm) {
    writeFileSync(
      join(bin, "pnpm"),
      '#!/bin/sh\nprintf \'pnpm %s in %s\\n\' "$*" "$PWD" > "$NOMO_TEST_PNPM_LOG"\n',
      { mode: 0o755 },
    );
  }
  const pidLog = join(home, "node-pid.log");
  const env = {
    ...process.env,
    HOME: home,
    PATH: `${bin}:${process.env.PATH}`,
    NOMO_TEST_ARGV_LOG: argvLog,
    NOMO_TEST_STDIN_LOG: stdinLog,
    NOMO_TEST_PNPM_LOG: pnpmLog,
    NOMO_TEST_PID_LOG: pidLog,
    // The fixture tree is where `makeTree` puts it, so every test is one line
    // of setup rather than a per-test env override. The one test that cares
    // about the default deletes this again.
    NOMO_HOME: join(home, "tree"),
  };
  // Legacy names from the developer's own shell must not leak in: an ambient
  // VOID_HOME would answer for the tree a test means to be unset. Each test
  // that wants a legacy name sets it explicitly on top of this.
  for (const key of Object.keys(env)) {
    if (key.startsWith("VOID_")) delete env[key];
  }
  const sh = (command, args, extra = {}) =>
    spawnSync(command, args, { encoding: "utf8", env, timeout: 60_000, ...extra });

  return { home, bin, argvLog, stdinLog, pnpmLog, env, sh };
}


/**
 * A tree that already looks installed, so the installer's clone step is never
 * reached. `git init` is what makes it a tree the installer reuses rather than
 * refuses. `dir` places it somewhere other than the fixture default, for the
 * tests that need the tree at the documented default path or under a legacy
 * name.
 */
function makeTree(home, { withModules = true, stale = false, dir } = {}) {
  const tree = dir ?? join(home, "tree");
  mkdirSync(join(tree, "packages", "cli", "bin"), { recursive: true });
  writeFileSync(join(tree, entry), "#!/usr/bin/env node\n");
  writeFileSync(join(tree, "pnpm-lock.yaml"), "lockfileVersion: '9.0'\n");
  spawnSync("git", ["init", "--quiet", tree], { encoding: "utf8", timeout: 30_000 });
  if (withModules) mkdirSync(join(tree, "node_modules"), { recursive: true });
  // The installer compares the lockfile against node_modules by mtime, so the
  // fixture has to place them deliberately in both directions.
  const now = new Date();
  const later = new Date(Date.now() + 10_000);
  const lock = stale ? later : now;
  utimesSync(join(tree, "pnpm-lock.yaml"), now, lock);
  if (withModules) utimesSync(join(tree, "node_modules"), now, stale ? now : later);
  return tree;
}

const outputOf = (run) => `${run.stdout ?? ""}${run.stderr ?? ""}`;
const readLog = (path) => {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return null;
  }
};

/** The argv the fake node was handed, with the entry path it was given removed. */
function forwardedArgs(argvLog, tree) {
  const raw = readLog(argvLog);
  if (raw === null) return null;
  const parts = raw.split("\0");
  parts.pop(); // printf always writes a trailing separator
  assert.equal(parts[0], join(tree, entry), "the launcher must exec the tree's CLI entry");
  return parts.slice(1);
}

test("the launcher execs the CLI instead of forking a shell around it", async () => {
  const box = sandbox({ fakeNode: true });
  try {
    makeTree(box.home);
    assert.equal(box.sh(installer, []).status, 0);

    // The fake node reports the pid it runs as. Because the launcher execs, that
    // pid is the pid the terminal started: the shell is replaced, so the TUI's
    // stdin, its signals and its exit status belong to the process the
    // operator is looking at. A plain `node ... "$@"` would leave an
    // intervening shell holding all three, which no argv assertion can see.
    const child = spawn(join(box.home, ".local", "bin", "nomo"), [], {
      env: box.env,
      stdio: ["ignore", "ignore", "ignore"],
    });
    const code = await new Promise((resolve) => child.on("close", resolve));

    assert.equal(code, 0);
    assert.equal(
      readLog(box.env.NOMO_TEST_PID_LOG)?.trim(),
      String(child.pid),
      "the CLI must be the process the launcher was started as, not a child of it",
    );
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("a bare nomo invocation resolves to the TUI command", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const tree = makeTree(box.home);
    const installed = box.sh(installer, []);
    assert.equal(installed.status, 0, outputOf(installed));

    const run = box.sh(join(box.home, ".local", "bin", "nomo"), [], { input: "" });
    assert.equal(run.status, 0, outputOf(run));

    const forwarded = forwardedArgs(box.argvLog, tree);
    assert.deepEqual(forwarded, [], "no arguments may be invented for the CLI");
    const parsed = parseInvocation(withDefaultTui(forwarded));
    assert.ok(parsed.ok, "a bare nomo must name a real command");
    assert.equal(parsed.command, "tui");
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("arguments reach the CLI untouched, including empty and quoted ones", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const tree = makeTree(box.home);
    assert.equal(box.sh(installer, []).status, 0);

    const args = [
      "run",
      "ledger",
      "--since",
      "",
      "two words",
      "quote'and\"double",
      "$HOME",
      "*",
      "--",
      "-x",
    ];
    const run = box.sh(join(box.home, ".local", "bin", "nomo"), args, { input: "" });
    assert.equal(run.status, 0, outputOf(run));
    assert.deepEqual(forwardedArgs(box.argvLog, tree), args);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("stdin passes through the launcher untouched", () => {
  const box = sandbox({ fakeNode: true });
  try {
    makeTree(box.home);
    assert.equal(box.sh(installer, []).status, 0);
    box.sh(join(box.home, ".local", "bin", "nomo"), [], { input: "typed at the prompt\n" });
    assert.equal(readLog(box.stdinLog), "typed at the prompt\n");
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("a missing tree refuses, explains the recovery, and runs no CLI", () => {
  const box = sandbox({ fakeNode: true });
  try {
    makeTree(box.home);
    assert.equal(box.sh(installer, []).status, 0);
    rmSync(join(box.home, "tree"), { recursive: true, force: true });

    const run = box.sh(join(box.home, ".local", "bin", "nomo"), [], { input: "" });
    assert.notEqual(run.status, 0, "a launcher with no tree must not report success");
    assert.match(run.stderr, /no NOMO install at/);
    assert.match(run.stderr, /install-nomo\.sh/);
    assert.match(run.stderr, /git clone https:\/\/github\.com\/Dawe583\/void\.git/);
    assert.equal(readLog(box.argvLog), null, "nothing may be exec'd when the tree is gone");
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("NOMO_HOME is read from the environment, with the documented default", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const tree = makeTree(box.home);
    const withTree = { ...box.env, NOMO_HOME: tree };
    assert.equal(box.sh(installer, [], { env: withTree }).status, 0);

    const run = box.sh(join(box.home, ".local", "bin", "nomo"), ["--version"], {
      input: "",
      env: withTree,
    });
    assert.equal(run.status, 0, outputOf(run));
    assert.deepEqual(forwardedArgs(box.argvLog, tree), ["--version"]);

    // Without the variable the launcher looks at ~/.local/share/nomo-cli,
    // which does not exist in this sandbox: the default is the documented path
    // and not the tree the installer happened to be pointed at.
    const without = { ...box.env };
    delete without.NOMO_HOME;
    const elsewhere = box.sh(join(box.home, ".local", "bin", "nomo"), [], {
      input: "",
      env: without,
    });
    assert.notEqual(elsewhere.status, 0);
    assert.match(elsewhere.stderr, /no NOMO install at .*\.local\/share\/nomo-cli/);

  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("a legacy VOID_HOME alone installs and runs the same tree NOMO_HOME would", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const tree = makeTree(box.home, { dir: join(box.home, "void-tree") });
    const legacy = { ...box.env, VOID_HOME: tree };
    delete legacy.NOMO_HOME;

    const installed = box.sh(installer, [], { env: legacy });
    assert.equal(installed.status, 0, outputOf(installed));
    assert.match(installed.stdout, /reusing existing NOMO tree/);

    // The launcher reads the same names the installer resolved, or a machine
    // that only ever exported the legacy one installs into a tree the launcher
    // cannot find.
    const run = box.sh(join(box.home, ".local", "bin", "nomo"), ["--version"], {
      input: "",
      env: legacy,
    });
    assert.equal(run.status, 0, outputOf(run));
    assert.deepEqual(forwardedArgs(box.argvLog, tree), ["--version"]);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("NOMO_HOME wins over VOID_HOME when both are set", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const owned = makeTree(box.home);
    const legacy = makeTree(box.home, { dir: join(box.home, "void-tree") });
    const both = { ...box.env, NOMO_HOME: owned, VOID_HOME: legacy };

    assert.equal(box.sh(installer, [], { env: both }).status, 0);
    const run = box.sh(join(box.home, ".local", "bin", "nomo"), ["--version"], {
      input: "",
      env: both,
    });
    assert.equal(run.status, 0, outputOf(run));
    assert.deepEqual(forwardedArgs(box.argvLog, owned), ["--version"]);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("an empty NOMO_HOME is the operator's choice and does not fall back", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const legacy = makeTree(box.home, { dir: join(box.home, "void-tree") });
    // Empty is not unset. Silently reading VOID_HOME here would run with a tree
    // nobody asked for, so the installer is expected to fail loudly instead.
    const empty = { ...box.env, NOMO_HOME: "", VOID_HOME: legacy };
    const installed = box.sh(installer, [], { env: empty });
    assert.notEqual(installed.status, 0);
    assert.equal(
      readLog(box.argvLog),
      null,
      "no tree may be launched after an empty NOMO_HOME",
    );

    // The launcher resolves the same names, so it must refuse the same way.
    makeTree(box.home);
    assert.equal(box.sh(installer, []).status, 0);
    const run = box.sh(join(box.home, ".local", "bin", "nomo"), [], {
      input: "",
      env: empty,
    });
    assert.notEqual(run.status, 0, "the launcher must not fall back to VOID_HOME");
    assert.match(run.stderr, /no NOMO install at/);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("only NOMO_ names are aliased, so VOID_HOME never answers for anything else", () => {
  const box = sandbox({ fakeNode: true });
  try {
    // An unrelated name that merely starts with the legacy prefix must not be
    // mistaken for a spelling of a setting the installer owns.
    const env = { ...box.env, VOID_DATA_DIR: join(box.home, "void-data") };
    delete env.NOMO_HOME;
    const tree = makeTree(box.home, { dir: join(box.home, ".local", "share", "nomo-cli") });
    const installed = box.sh(installer, [], { env });
    assert.equal(installed.status, 0, outputOf(installed));
    assert.match(installed.stdout, /reusing existing NOMO tree/);

    const run = box.sh(join(box.home, ".local", "bin", "nomo"), ["--version"], {
      input: "",
      env,
    });
    assert.equal(run.status, 0, outputOf(run));
    assert.deepEqual(forwardedArgs(box.argvLog, tree), ["--version"]);
    assert.equal(
      existsSync(join(box.home, "void-data")),
      false,
      "an unrelated legacy name must not be read at all",
    );
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("the installed launcher keeps the shape the repo root launcher is held to", () => {
  const box = sandbox({ fakeNode: true });
  try {
    makeTree(box.home);
    assert.equal(box.sh(installer, []).status, 0);
    const text = readFileSync(join(box.home, ".local", "bin", "nomo"), "utf8");

    // release-packaging.test.mjs holds the repo root to exactly this shape. A
    // second convention here would leave two launchers to keep in agreement.
    assert.match(text, /^#!\/bin\/sh\n/);
    assert.match(text, /packages\/cli\/bin\/nomo\.mjs/);
    assert.match(text, /exec node .*"\$@"/);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("the installer reuses an existing tree and skips current dependencies", () => {
  const box = sandbox({ fakeNode: true, fakePnpm: true });
  try {
    makeTree(box.home);
    const first = box.sh(installer, []);
    assert.equal(first.status, 0, outputOf(first));
    assert.match(first.stdout, /reusing existing NOMO tree/);
    assert.equal(readLog(box.pnpmLog), null, "current dependencies must not be reinstalled");

    const second = box.sh(installer, []);
    assert.equal(second.status, 0, outputOf(second));
    assert.match(second.stdout, /dependencies already current/);
    assert.equal(readLog(box.pnpmLog), null, "a second run must also install nothing");
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("prints the command that its installed launcher actually provides", () => {
  const box = sandbox({ fakeNode: true, fakePnpm: true });
  try {
    makeTree(box.home);
    const run = box.sh(installer, []);
    assert.equal(run.status, 0, outputOf(run));
    assert.match(run.stdout, /^  nomo$/m);
    assert.doesNotMatch(run.stdout, /^  void$/m);
    assert.equal(existsSync(join(box.home, ".local", "bin", "nomo")), true);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("dependencies install when node_modules is absent or older than the lockfile", () => {
  for (const shape of [
    { withModules: false, stale: false },
    { withModules: true, stale: true },
  ]) {
    const box = sandbox({ fakePnpm: true });
    try {
      const tree = makeTree(box.home, shape);
      const run = box.sh(installer, []);
      assert.equal(run.status, 0, outputOf(run));
      assert.equal(
        readLog(box.pnpmLog),
        `pnpm install --frozen-lockfile in ${tree}\n`,
        "pnpm must run from the tree it was told to install",
      );
    } finally {
      rmSync(box.home, { recursive: true, force: true });
    }
  }
});

test("the installer refuses to overwrite a launcher that is not its own", () => {
  const box = sandbox({ fakeNode: true });
  try {
    makeTree(box.home);
    const launcher = join(box.home, ".local", "bin", "nomo");
    mkdirSync(join(box.home, ".local", "bin"), { recursive: true });
    const foreign = "#!/bin/sh\necho somebody elses tool\n";
    writeFileSync(launcher, foreign);

    const run = box.sh(installer, []);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /refusing to overwrite/);
    assert.equal(readFileSync(launcher, "utf8"), foreign);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("a NOMO_HOME that is not a checkout is refused, not half written", () => {
  const box = sandbox({ fakeNode: true });
  try {
    const tree = join(box.home, "not-a-tree");
    mkdirSync(tree, { recursive: true });
    writeFileSync(join(tree, "some-notes.txt"), "hello\n");

    const run = box.sh(installer, [], { env: { ...box.env, NOMO_HOME: tree } });
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /exists but holds no NOMO checkout/);
    assert.deepEqual(readdirSync(tree), ["some-notes.txt"]);
    assert.equal(
      readLog(box.argvLog),
      null,
      "the launcher must not be written when the tree was refused",
    );
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});

test("--help explains the install and an unknown argument is refused", () => {
  const box = sandbox();
  try {
    const help = box.sh(installer, ["--help"]);
    assert.equal(help.status, 0, outputOf(help));
    assert.match(help.stdout, /NOMO_HOME/);
    assert.match(help.stdout, /\.local\/share\/nomo-cli/);
    assert.match(help.stdout, /\.local\/bin/);
    assert.match(
      help.stdout,
      /VOID_HOME/,
      "the legacy name must stay documented as accepted",
    );

    const unknown = box.sh(installer, ["--reinstall-everything"]);
    assert.equal(unknown.status, 1);
    assert.match(unknown.stderr, /unknown argument --reinstall-everything/);
  } finally {
    rmSync(box.home, { recursive: true, force: true });
  }
});